def spread_side(y_at, keys, pitch, lo_of, hi_of):
    """把同一侧的接点拉开到至少 pitch（上下的先后按原有顺序，不重新排队）。

    为什么需要它：slot_y() 只在框高里按对端 y 扇开，align_ports() 又会把几条边拉到
    同一高度 —— 两者都没保证“最终间距”，实测 S11 入侧挤到 2.3px（两条线看着像一根）。
    做法：以原有中点为基准等距排开，再把每个人夹到本框可用区间内；
    端口多于高度时按可用高度收缩间距（宁可挤一点，也不把线头接到框外）。
    """
    if len(keys) < 2:
        return {}
    order = sorted(keys, key=lambda k: y_at[k])
    lo_all = max(min(lo_of[k] for k in keys), min(y_at[k] for k in keys))
    hi_all = min(max(hi_of[k] for k in keys), max(y_at[k] for k in keys))
    pitch = min(float(pitch), (hi_all - lo_all) / (len(keys) - 1))
    if pitch <= 0:
        return {}
    center = sum(y_at[k] for k in keys) / len(keys)
    got = {}
    for rank, k in enumerate(order):
        y = center + (len(keys) - 1) * pitch / 2 - rank * pitch
        got[k] = min(max(y, lo_of[k]), hi_of[k])
    return got

def spread_side(y_at, keys, pitch, lo_of, hi_of):
    """把同一侧的接点拉开到至少 pitch（上下的先后按原有顺序，不重新排队）。

    为什么需要它：slot_y() 只在框高里按对端 y 扇开，align_ports() 又会把几条边拉到
    同一高度 —— 两者都没保证“最终间距”，实测 S11 入侧挤到 2.3px（两条线看着像一根）。
    做法：以原有中点为基准等距排开，再夹到本框可用区间内；端口多于高度时
    按可用高度收缩间距（宁可挤一点，也不把线头接到框外）。
    只往“离自己原来位置”的方向求最小扰动，所以不会把接点甩到对侧。
    """
    if len(keys) < 2:
        return {}
    order = sorted(keys, key=lambda k: y_at[k])
    n = len(order)
    lo_all = max(min(lo_of[k] for k in keys), min(y_at[k] for k in keys))
    hi_all = min(max(hi_of[k] for k in keys), max(y_at[k] for k in keys))
    pitch = min(float(pitch), (hi_all - lo_all) / (n - 1))
    if pitch <= 0:
        return {}
    center = sum(y_at[k] for k in keys) / n
    want = {k: center + (n - 1) * pitch / 2 - rank * pitch for rank, k in enumerate(order)}

    def shift(d):
        """整组平移 d，逐人夹到本框区间（顺序不会反过来：间距 >= pitch）。"""
        return {k: min(max(want[k] + d, lo_of[k]), hi_of[k]) for k in order}

    got = shift(0.0)
    best = sum(abs(got[k] - y_at[k]) for k in order)
    step = max(pitch / 4, 1.0)
    for i in range(1, 64):                                  # 找扰动最小的那个平移量
        for d in (i * step, -i * step):
            cand = shift(d)
            cost = sum(abs(cand[k] - y_at[k]) for k in order)
            if cost < best - 0.01:
                got, best = cand, cost
                break
    return got

