def group_overlaps(groups, clear=0.0):
    """互相压住（横、纵重叠都超过 clear）的层框对，按重叠面积从大到小。"""
    out = []
    for a, b in itertools.combinations(groups, 2):
        ox = min(a["x"] + a["w"], b["x"] + b["w"]) - max(a["x"], b["x"])
        oy = min(a["y"] + a["h"], b["y"] + b["h"]) - max(a["y"], b["y"])
        if ox > clear and oy > clear:
            out.append((ox * oy, ox, oy, a, b))
    return sorted(out, key=lambda t: -t[0])


def layer_rank(groups, edges_between):
    """层与层的上下次序：按依赖拓扑排，被依赖的在上（和"左出右入"同一个方向感）。

    为什么不能"谁面积大谁当主轴、小的贴过去"：那只是把重叠消掉，层序会变成随机的 ——
    实测外部输入层被推到基础层下面，读图的人第一句就是"输入怎么在中间"。
    边的方向本身就是语义（S02 -> S08 -> S15），层的纵向次序必须由它定。
    """
    ids = [g["id"] for g in groups]
    down, indeg = collections.defaultdict(set), {i: 0 for i in ids}
    for a, b in edges_between:
        if a in indeg and b in indeg and a != b and b not in down[a]:
            down[a].add(b)
            indeg[b] += 1
    order, queue = [], [i for i in ids if not indeg[i]]
    while queue:
        cur = queue.pop(0)
        order.append(cur)
        for nxt in sorted(down[cur]):
            indeg[nxt] -= 1
            if not indeg[nxt]:
                queue.append(nxt)
    rank = {i: r for r, i in enumerate(order)}
    left = sorted((i for i in ids if i not in rank),          # 环里的层：按现状补进去
                  key=lambda i: next(g["y"] for g in groups if g["id"] == i))
    for k, i in enumerate(left):
        rank[i] = len(order) + k
    return rank


def stack_groups(groups, ny, clear=18.0, edges_between=(), min_move=60.0):
    """层框压住就整层下移（改成员坐标；层框是成员的包围盒）。返回是否彻底解开。

    为什么只纵不横：横向 = 层的左右关系，由分层算法按依赖定，改它就是改图的含义；
    纵向只是同一堆里的排布。谁上谁下由依赖拓扑定（见 layer_rank），每轮只解重叠最大的
    一对 —— 一次挪多层会把图推得忽远忽近，也看不出是哪一步推坏的。

    为什么改成员而不是层框：层框是成员的包围盒，只挪层框的话下一轮又被成员算回去。
    min_move：小于这个数就不动了 —— 差几像素说明本来就快解开，为它把一层全搬走不值得
    （会牵动这一层所有边的走线）。
    """
    for _ in range(len(groups) * len(groups) + 4):
        hits = group_overlaps(groups, clear)
        if not hits:
            return True
        rank = layer_rank(groups, edges_between)
        _area, _ox, _oy, a, b = max(hits, key=lambda t: t[0])
        upper, lower = (a, b) if rank[a["id"]] <= rank[b["id"]] else (b, a)
        need = (upper["y"] + upper["h"] + clear) - lower["y"]
        if abs(need) < min_move:
            return not group_overlaps(groups, clear)
        for m in lower["members"]:
            if m in ny:
                ny[m] += need                        # 成员中心整体下移
        relayout(groups, ny)                         # 层框按新成员坐标重算
    return not group_overlaps(groups, clear)


def stack_layers(layers_of, ny, h_of, rank, clear=18.0, min_move=60.0):
    """把纵向叠住的层按依赖次序排开（改成员 y，不改 x）。返回是否全部解开。

    为什么只纵不横：横向 = 层的左右关系，由分层算法按依赖定出来，改它就是改图的含义；
    纵向只是同一堆里的排布。所以只在纵向下移，且下移的是成员坐标 —— 层框是成员的包围盒，
    只挪层框的话下一轮又被成员算回去（踩过一次）。

    谁上谁下由依赖拓扑定（见 layer_rank）；每轮只解"叠住的那一堆"里次序最靠后的一个，
    一次挪多层会把图推得忽远忽近，也看不出是哪一步推坏的。
    min_move：小于这个数就不动了 —— 差几像素说明本来就快解开，为它把一层全搬走不值得。
    """
    for _ in range(len(layers_of) * len(layers_of) + 4):
        rect = {gid: layer_rect(members, ny, h_of, pad)
                for gid, (members, pad) in layers_of.items()}
        hits = [(min(a[0] + a[2], b[0] + b[2]) - max(a[0], b[0]),
                 min(a[1] + a[3], b[1] + b[3]) - max(a[1], b[1]), x, y)
                for (x, a), (y, b) in itertools.combinations(rect.items(), 2)]
        hits = [h for h in hits if h[0] > clear and h[1] > clear]
        if not hits:
            return True
        # 叠住的那一堆里，次序最靠后（依赖最下游）的那个往下挪
        stacked = {g for h in hits for g in (h[2], h[3])}
        victim = max(stacked, key=lambda g: rank.get(g, 0))
        others = [rect[g] for h in hits for g in (h[2], h[3]) if g != victim]
        need = max(r[1] + r[3] + clear for r in others) - rect[victim][1]
        if abs(need) < min_move:
            return False
        for m in layers_of[victim][0]:
            if m in ny:
                ny[m] += need
    return False


