        pts = geo[idx]
        base = pts[k][0]
        geo[idx] = [(x + dx, y) if abs(x - base) < 0.6 and m >= k else (x, y)
                    for m, (x, y) in enumerate(pts)]

    lanes = []
    for idx, pts in geo.items():
        for k in range(1, len(pts) - 1):
            span = vspan(pts, k)
            if span:
                lanes.append([pts[k][0], idx, k, span])
    lanes.sort(key=lambda t: t[0])

    def cluster(seed, pool, pitch):
        """和 seed 纵向叠住、x 相距不到 pitch 的通道（互相传递，取闭包）。"""
        got, queue = {id(seed)}, [seed]
        while queue:
            cur = queue.pop()
            for c in pool:
                if id(c) in got or c[1] == cur[1]:           # 同一条边自己的两段：不算
                    continue
                if abs(c[0] - cur[0]) >= pitch:
                    continue
                if min(c[3][1], cur[3][1]) - max(c[3][0], cur[3][0]) <= 2:
                    continue                                 # 纵向不重叠：各走各的
                got.add(id(c))
                queue.append(c)
        return [c for c in pool if id(c) in got]

    left, done = 0, set()
    for seed in lanes:
        if id(seed) in done:
            continue
        group = sorted(cluster(seed, lanes, pitch), key=lambda t: t[0])
        done |= {id(g) for g in group}
        if len(group) < 2:
            continue
        x = (group[0][0] + group[-1][0]) / 2 - pitch * (len(group) - 1) / 2
        for lane in group:
